import type { SubjectId } from './data';
import type { QuizQuestion } from './types';

const AT = '2026-01-01T00:00:00.000Z';
let index = 0;
/**
 * Ids sit in their own `deep-` range with their own counter, so adding questions here
 * never renumbers the `seed-` bank (ids are what attempts and the retry ladder store).
 */
function q(subject: SubjectId, chapterId: string, question: string, options: string[], answer: number, explanation: string): QuizQuestion {
  index += 1;
  return {
    id: `deep-${String(index).padStart(3, '0')}`, subject, chapterId, question, options, answer,
    explanation,
    source: 'গভীরতা ব্যাংক · পাঠ্যবইয়ের তথ্য', createdAt: AT, bank: true,
  };
}

